// формує пошукові запити для Google Places на основі комбінацій "місто + категорія". За один запуск бере обмежену кількість запитів. Щодня змінює ділянку списку, щоб поступово охопити всі міста та категорії й непровіряти одні й ті самі запити. 
const cfg = $input.first()?.json ?? {};

const asArray = (v) =>
  Array.isArray(v) ? v.filter((x) => typeof x === 'string' && x.trim().length > 0) : [];

const asInt = (v, fallback) => {
  const n = Number(v);
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : fallback;
};

const cities = asArray(cfg.cities);
const categories = asArray(cfg.categories);

if (cities.length === 0 || categories.length === 0) {
  throw new Error(
    'Config error: "cities" and "categories" must both be non-empty arrays in the Config node.',
  );
}

const modifiersRaw = Array.isArray(cfg.queryModifiers) ? cfg.queryModifiers : [];
const modifiers = modifiersRaw.filter((m) => typeof m === 'string');
const modifierList = modifiers.length > 0 ? modifiers : [''];

const testMode = cfg.testMode === true;
const maxSearches = testMode ? asInt(cfg.testMaxSearches, 2) : asInt(cfg.maxSearchesPerRun, 12);
const pageSize = Math.min(20, asInt(cfg.maxResultsPerSearch, 20));

const pairs = [];
for (const city of cities) {
  for (const category of categories) {
    pairs.push({ city, category });
  }
}

// Щоденна ротація: кожного календарного дня вибирається інша ділянка всього набору пошукових комбінацій.
const dayIndex = Math.floor(Date.now() / 86400000);
const start = (dayIndex * maxSearches) % pairs.length;
const modifier = modifierList[dayIndex % modifierList.length] ?? '';

const languageCode = typeof cfg.languageCode === 'string' && cfg.languageCode ? cfg.languageCode : 'uk';
const regionCode = typeof cfg.regionCode === 'string' && cfg.regionCode ? cfg.regionCode : 'UA';

const take = Math.min(maxSearches, pairs.length);
const out = [];

for (let i = 0; i < take; i++) {
  const pair = pairs[(start + i) % pairs.length];
  const query = [modifier, pair.category, pair.city].filter((p) => p && p.trim()).join(' ').trim();

  out.push({
    json: {
      query,
      city: pair.city,
      category: pair.category,
      pageSize,
      languageCode,
      regionCode,
      searchIndex: i,
      rotationDay: dayIndex,
      testMode,
    },
  });
}

return out;

// Перетворює сирі результати Google Places на кандидатів для лідів. Як що один пошук завершився помилкою або нічого незнайшов весь робочий процес не зупиняється, а продовжує обробку інших результатів.

const queries = $('формування пошукових запитів').all().map((i) => i.json);
const items = $input.all();

const SOCIAL_HOST =
  /(?:^|\.)(facebook\.com|fb\.com|fb\.me|instagram\.com|tiktok\.com|t\.me|telegram\.me|vk\.com|linkedin\.com|youtube\.com|twitter\.com|x\.com)$/i;

// Визначає сайти-заглушки: сторінки-конструктори або link-in-bio, а не повноцінний сайт бізнесу.
const WEAK_HOST = /(?:^|\.)(business\.site|sites\.google\.com|linktr\.ee|taplink\.cc|carrd\.co)$/i;

function parseUrl(value) {
  if (typeof value !== 'string' || value.trim().length === 0) return null;
  try {
    const url = new URL(value.trim());
    if (url.protocol !== 'http:' && url.protocol !== 'https:') return null;
    return url;
  } catch {
    return null;
  }
}

function errorText(err) {
  if (!err) return 'unknown error';
  if (typeof err === 'string') return err.slice(0, 300);
  if (typeof err.message === 'string') return err.message.slice(0, 300);
  try {
    return JSON.stringify(err).slice(0, 300);
  } catch {
    return 'unreadable error object';
  }
}

const stats = {
  searchesAttempted: items.length,
  searchesFailed: 0,
  searchesEmpty: 0,
  placesSeen: 0,
  skippedClosed: 0,
  skippedHasWebsite: 0,
  skippedInvalidRecord: 0,
  duplicatesWithinRun: 0,
};

const errors = [];
const candidates = [];
const seenInRun = new Set();

for (let i = 0; i < items.length; i++) {
  const ctx = queries[i] ?? {};
  const data = items[i]?.json ?? {};
  const label = ctx.query ?? 'search #' + (i + 1);

  // Перевіряє два типи помилок: помилку від n8n або помилку, яку повернув Google API.
  if (data.error) {
    stats.searchesFailed++;
    errors.push('Places search failed for "' + label + '": ' + errorText(data.error));
    continue;
  }

  const places = Array.isArray(data.places) ? data.places : [];
  if (places.length === 0) {
    stats.searchesEmpty++;
    continue;
  }

  for (const place of places) {
    stats.placesSeen++;

    const placeId = typeof place?.id === 'string' ? place.id.trim() : '';
    const rawName = place?.displayName?.text;
    const name = typeof rawName === 'string' ? rawName.trim() : '';

    if (!placeId || !name) {
      stats.skippedInvalidRecord++;
      continue;
    }

    if (place.businessStatus && place.businessStatus !== 'OPERATIONAL') {
      stats.skippedClosed++;
      continue;
    }

    if (seenInRun.has(placeId)) {
      stats.duplicatesWithinRun++;
      continue;
    }
    seenInRun.add(placeId);

    const url = parseUrl(place.websiteUri);
    const host = url ? url.hostname.replace(/^www\./i, '') : '';
    const isSocialOnly = host ? SOCIAL_HOST.test(host) : false;
    const isWeakSite = host ? WEAK_HOST.test(host) : false;
    const hasRealWebsite = Boolean(host) && !isSocialOnly && !isWeakSite;

    // Головна задача Lead Hunter — залишати тільки бізнеси, у яких немає повноцінного власного сайту.
    if (hasRealWebsite) {
      stats.skippedHasWebsite++;
      continue;
    }

    const rating = Number(place.rating);
    const reviews = Number(place.userRatingCount);

    candidates.push({
      place_id: placeId,
      name,
      city: typeof ctx.city === 'string' ? ctx.city : '',
      category: typeof ctx.category === 'string' ? ctx.category : '',
      google_type:
        (typeof place?.primaryTypeDisplayName?.text === 'string'
          ? place.primaryTypeDisplayName.text
          : place?.primaryType) ?? '',
      address: typeof place.formattedAddress === 'string' ? place.formattedAddress : '',
      phone:
        (typeof place.internationalPhoneNumber === 'string' ? place.internationalPhoneNumber : '') ||
        (typeof place.nationalPhoneNumber === 'string' ? place.nationalPhoneNumber : ''),
      website: url ? url.href : '',
      website_is_social_only: isSocialOnly,
      website_is_weak: isWeakSite,
      maps_url: typeof place.googleMapsUri === 'string' ? place.googleMapsUri : '',
      rating: Number.isFinite(rating) ? rating : 0,
      reviews: Number.isFinite(reviews) ? reviews : 0,
      source_query: label,
    });
  }
}

stats.candidatesFound = candidates.length;

return [{ json: { candidates, stats, errors } }];

// Видаляє бізнеси, які вже знаходилися раніше.

// Отримує збережені бізнеси з Data Table.

// Отримує кандидатів із попереднього кроку workflow.

// Завжди повертає результат, навіть якщо нових кандидатів немає.

const source = $('нормалізація та фільтрація бізнесів').first()?.json ?? {};
const cfg = $('Конфігурація').first()?.json ?? {};

const candidates = Array.isArray(source.candidates) ? source.candidates : [];
const stats = Object.assign({}, source.stats ?? {});
const errors = Array.isArray(source.errors) ? source.errors.slice() : [];

const rawRows = $input.all().map((i) => i?.json ?? {});

// Якщо Data Table недоступна, продовжує без перевірки дублікатів,
// щоб помилка пам'яті не зупинила весь workflow.
for (const row of rawRows) {
  if (row && row.error) {
    errors.push('Memory lookup (Data Table) failed - duplicate protection is degraded this run.');
  }
}

const knownRows = rawRows.filter((r) => r && !r.error && (r.place_id || r.name));

const normalise = (v) =>
  String(v ?? '')
    .toLowerCase()
    .replace(/[^a-zЀ-ӿ0-9]+/gi, ' ')
    .trim();

const nameKey = (name, city) => normalise(name) + '|' + normalise(city);

const knownIds = new Set();
const knownNames = new Set();

for (const row of knownRows) {
  if (row.place_id) knownIds.add(String(row.place_id));
  if (row.name) knownNames.add(nameKey(row.name, row.city));
}

stats.knownBusinessesInMemory = knownRows.length;

const testMode = cfg.testMode === true;
const maxCandidatesRaw = testMode ? cfg.testMaxCandidates : cfg.maxCandidatesPerRun;
const maxCandidatesNum = Number(maxCandidatesRaw);
const maxCandidates =
  Number.isFinite(maxCandidatesNum) && maxCandidatesNum > 0 ? Math.floor(maxCandidatesNum) : 60;

const fresh = [];
let duplicates = 0;

for (const candidate of candidates) {
  const id = String(candidate.place_id ?? '');
  const key = nameKey(candidate.name, candidate.city);

  if ((id && knownIds.has(id)) || knownNames.has(key)) {
    duplicates++;
    continue;
  }

  if (id) knownIds.add(id);
  knownNames.add(key);
  fresh.push(candidate);

  if (fresh.length >= maxCandidates) break;
}

stats.duplicatesSkipped = duplicates;
stats.newCandidates = fresh.length;
stats.testMode = testMode;

if (fresh.length === 0) {
  return [{ json: { _noLeads: true, _stats: stats, _errors: errors } }];
}

return fresh.map((c) => ({ json: Object.assign({}, c, { _noLeads: false, _stats: stats, _errors: errors }) }));

// Формує щоденний звіт для Telegram у форматі HTML та ділить його на частини,
// щоб не перевищити ліміт довжини повідомлення.

const leads = $('ранжування та застосування лімітів')
  .all()
  .map((i) => i.json)
  .filter((l) => l && l._noLeads !== true);

const memoryNode = $('відсікання нових бізнесів').first()?.json ?? {};
const stats = memoryNode._stats ?? {};
const errors = Array.isArray(memoryNode._errors) ? memoryNode._errors : [];

const cfg = $('Конфігурація').first()?.json ?? {};
const maxInReport = Number(cfg.maxLeadsInTelegramReport);
const limit = Number.isFinite(maxInReport) && maxInReport > 0 ? Math.floor(maxInReport) : 15;

const esc = (v) =>
  String(v ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

const SERVICE_LABELS = {
  landing_page: 'Лендінг',
  multi_page_site: 'Багатосторінковий сайт',
  online_store: 'Інтернет-магазин',
  booking_site: 'Сайт із записом',
  portfolio_site: 'Портфоліо',
  google_business_only: 'Тільки Google профіль',
};

const today = new Date().toISOString().slice(0, 10);
const shown = leads.slice(0, limit);

const header = [];
header.push('<b>🎯 AI Lead Hunter — ' + esc(today) + '</b>');
if (stats.testMode === true) header.push('<i>⚠️ TEST MODE увімкнено — ліміти занижені</i>');
header.push('');
header.push('<b>Нові ліди: ' + shown.length + '</b>' + (leads.length > shown.length ? ' (з ' + leads.length + ')' : ''));
header.push(
  'Пошуків: ' +
    (stats.searchesAttempted ?? 0) +
    ' · Знайдено закладів: ' +
    (stats.placesSeen ?? 0) +
    ' · Вже мали сайт: ' +
    (stats.skippedHasWebsite ?? 0),
);
header.push(
  'Дублікатів пропущено: ' +
    (stats.duplicatesSkipped ?? 0) +
    ' · В памʼяті: ' +
    (stats.knownBusinessesInMemory ?? 0),
);
if ((stats.searchesFailed ?? 0) > 0) {
  header.push('⚠️ Невдалих пошуків: ' + stats.searchesFailed);
}
header.push('');

const blocks = [];

shown.forEach((lead, index) => {
  const lines = [];
  lines.push(
    '<b>' + (index + 1) + '. ' + esc(lead.name) + '</b> — <b>' + (Number(lead.lead_score) || 0) + '/100</b>',
  );
  lines.push('📍 ' + esc(lead.city) + ' · ' + esc(lead.category));
  if (lead.address) lines.push('🏠 ' + esc(lead.address));
  if (lead.phone) lines.push('📞 ' + esc(lead.phone));
  if (Number(lead.reviews) > 0) {
    lines.push('⭐ ' + esc(lead.rating) + ' (' + esc(lead.reviews) + ' відгуків)');
  }
  lines.push('🌐 Сайту немає' + (lead.has_social ? ', але є соцмережі' : ', соцмереж не знайдено'));
  if (lead.social_links) lines.push('🔗 ' + esc(lead.social_links));
  if (lead.lead_reason) lines.push('💡 ' + esc(lead.lead_reason));
  if (lead.pitch_angle) lines.push('🗣 <i>' + esc(lead.pitch_angle) + '</i>');
  const service = SERVICE_LABELS[lead.recommended_service] ?? lead.recommended_service;
  if (service) lines.push('🧩 Рекомендація: ' + esc(service));
  if (lead.maps_url) lines.push('🗺 <a href="' + esc(lead.maps_url) + '">Google Maps</a>');
  if (lead.ai_status !== 'ok') lines.push('<i>(оцінка без AI — резервний алгоритм)</i>');
  blocks.push(lines.join('\n'));
});

const footer = [];
if (errors.length > 0) {
  footer.push('');
  footer.push('<b>⚠️ Попередження цього запуску:</b>');
  for (const e of errors.slice(0, 5)) footer.push('• ' + esc(e));
}

// Ділимо звіт на повідомлення безпечного для Telegram розміру.
const MAX = 3500;
const messages = [];
let current = header.join('\n');

const push = (text) => {
  if (current.length + text.length + 2 > MAX) {
    messages.push(current);
    current = text;
  } else {
    current = current + '\n\n' + text;
  }
};

for (const block of blocks) push(block);
if (footer.length > 0) push(footer.join('\n'));

messages.push(current);

return messages
  .filter((m) => m && m.trim())
  .map((message, index) => ({
    json: { message, part: index + 1, totalParts: messages.length },
  }));

// Надсилає звіт, навіть якщо сьогодні не знайдено нових лідів.

const memoryNode = $('відсікання нових бізнесів').first()?.json ?? {};
const stats = memoryNode._stats ?? {};
const errors = Array.isArray(memoryNode._errors) ? memoryNode._errors : [];

const esc = (v) =>
  String(v ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

const today = new Date().toISOString().slice(0, 10);

const lines = [];
lines.push('<b>🎯 AI Lead Hunter — ' + esc(today) + '</b>');
if (stats.testMode === true) lines.push('<i>⚠️ TEST MODE увімкнено — ліміти занижені</i>');
lines.push('');
lines.push('<b>Нових лідів сьогодні немає.</b>');
lines.push('');
lines.push('Пошуків виконано: ' + (stats.searchesAttempted ?? 0));
lines.push('Закладів переглянуто: ' + (stats.placesSeen ?? 0));
lines.push('Вже мали власний сайт: ' + (stats.skippedHasWebsite ?? 0));
lines.push('Дублікатів (вже в памʼяті): ' + (stats.duplicatesSkipped ?? 0));
lines.push('Всього в базі: ' + (stats.knownBusinessesInMemory ?? 0));

if ((stats.searchesFailed ?? 0) > 0) {
  lines.push('');
  lines.push('⚠️ Невдалих пошуків: ' + stats.searchesFailed);
}

if (errors.length > 0) {
  lines.push('');
  lines.push('<b>⚠️ Попередження:</b>');
  for (const e of errors.slice(0, 5)) lines.push('• ' + esc(e));
}

lines.push('44');
lines.push('<i>Підказка: збільш maxSearchesPerRun або додай міста/категорії в ноді Config.</i>');

return [{ json: { message: lines.join('\n'), part: 1, totalParts: 1 } }];

// Формує повідомлення про критичну помилку workflow.
// Спрацьовує лише при повному падінні workflow.

const data = $input.first()?.json ?? {};

const esc = (v) =>
  String(v ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

const workflowName = data.workflow?.name ?? 'AI Lead Hunter';
const message = data.execution?.error?.message ?? 'Unknown error';
const node = data.execution?.lastNodeExecuted ?? 'unknown node';
const url = data.execution?.url ?? '';

const lines = [];
lines.push('<b>🚨 AI Lead Hunter — помилка виконання</b>');
lines.push('');
lines.push('<b>Workflow:</b> ' + esc(workflowName));
lines.push('<b>Нода:</b> ' + esc(node));
lines.push('<b>Помилка:</b> ' + esc(String(message).slice(0, 500)));
if (url) lines.push('');
if (url) lines.push('<a href="' + esc(url) + '">Відкрити виконання в n8n</a>');

return [{ json: { message: lines.join('\n') } }];

// Reads the optional web-presence lookup, then builds one strict-JSON OpenAI
// request per candidate.
//
// This node sits on BOTH branches of "Web Enrichment Enabled":
//   enrichment ON  -> input items are SerpAPI responses, 1:1 with candidates
//   enrichment OFF -> input items are the candidates themselves

const cfg = $('Конфігурація').first()?.json ?? {};
const enrichmentOn = cfg.enableWebEnrichment === true;

const candidates = $('відсікання нових бізнесів')
  .all()
  .map((i) => i.json)
  .filter((c) => c && c._noLeads !== true);

const inputs = $input.all();

const SOCIAL =
  /(facebook\.com|fb\.com|instagram\.com|tiktok\.com|t\.me|telegram\.me|linkedin\.com|youtube\.com)/i;

// Aggregators / registries / marketplaces - being listed there is not "having a website".
const DIRECTORY =
  /(prom\.ua|olx\.ua|all\.biz|youcontrol|opendatabot|clarity-project|edata|2gis|flamp|tripadvisor|booking\.com|work\.ua|rabota\.ua|ua-region|yellowpages|google\.|goo\.gl|doc\.ua|zakupki|misto|otzyv|zoon\.|hotline\.ua|rozetka|maps\.app)/i;

function readHost(link) {
  if (typeof link !== 'string' || !link.trim()) return '';
  try {
    return new URL(link.trim()).hostname.replace(/^www\./i, '');
  } catch {
    return '';
  }
}

function analyseSerp(response) {
  const result = {
    used: true,
    ok: false,
    socialLinks: [],
    possibleWebsites: [],
    note: '',
  };

  if (!response || response.error) {
    result.note = 'web lookup failed or was rate limited';
    return result;
  }

  const organic = Array.isArray(response.organic_results) ? response.organic_results : [];
  if (organic.length === 0) {
    result.ok = true;
    result.note = 'no web results found at all';
    return result;
  }

  for (const entry of organic.slice(0, 10)) {
    const host = readHost(entry?.link);
    if (!host) continue;
    if (SOCIAL.test(host)) {
      if (!result.socialLinks.includes(entry.link)) result.socialLinks.push(entry.link);
      continue;
    }
    if (DIRECTORY.test(host)) continue;
    if (!result.possibleWebsites.includes(host)) result.possibleWebsites.push(host);
  }

  result.ok = true;
  return result;
}

const SCHEMA = {
  type: 'json_schema',
  json_schema: {
    name: 'lead_assessment',
    strict: true,
    schema: {
      type: 'object',
      additionalProperties: false,
      required: [
        'needs_website',
        'lead_score',
        'confidence',
        'business_type_normalized',
        'reason',
        'pitch_angle',
        'recommended_service',
        'red_flags',
      ],
      properties: {
        needs_website: { type: 'boolean' },
        lead_score: { type: 'integer' },
        confidence: { type: 'string', enum: ['low', 'medium', 'high'] },
        business_type_normalized: { type: 'string' },
        reason: { type: 'string' },
        pitch_angle: { type: 'string' },
        recommended_service: {
          type: 'string',
          enum: [
            'landing_page',
            'multi_page_site',
            'online_store',
            'booking_site',
            'portfolio_site',
            'google_business_only',
          ],
        },
        red_flags: { type: 'array', items: { type: 'string' } },
      },
    },
  },
};

const SYSTEM_PROMPT = [
  'You qualify Ukrainian small businesses as sales leads for a web-design studio.',
  'A GOOD lead is a real, operating business with paying customers that has no proper website',
  '(no site at all, or only a social media page, or only a link-in-bio stub).',
  'A BAD lead is: a large chain or franchise, a government or municipal body, a business that clearly',
  'already has a real website, a marketplace listing rather than a business, or a business with no',
  'signs of real activity.',
  'lead_score is an integer 0-100. Higher means more worth contacting.',
  'Score higher when: the business has reviews and a decent rating, is a service business that sells',
  'appointments or custom work, and has only social media or nothing at all.',
  'Score lower when: almost no reviews, looks dormant, looks like a chain, or may already have a site.',
  'reason and pitch_angle must be written in Ukrainian, one or two short sentences each.',
  'pitch_angle is the concrete angle for a first cold outreach message to this specific business.',
  'Answer ONLY with the JSON object described by the schema.',
].join(' ');

const model = typeof cfg.aiModel === 'string' && cfg.aiModel ? cfg.aiModel : 'gpt-4o-mini';

const out = [];

for (let i = 0; i < candidates.length; i++) {
  const candidate = candidates[i];

  let enrichment;
  if (enrichmentOn) {
    enrichment = analyseSerp(inputs[i]?.json);
  } else {
    enrichment = { used: false, ok: false, socialLinks: [], possibleWebsites: [], note: 'web enrichment disabled in Config' };
  }

  const facts = {
    name: candidate.name,
    city: candidate.city,
    searched_category: candidate.category,
    google_type: candidate.google_type,
    address: candidate.address,
    phone: candidate.phone || 'unknown',
    google_rating: candidate.rating,
    google_review_count: candidate.reviews,
    website_field_on_google: candidate.website || 'EMPTY',
    website_is_social_page_only: candidate.website_is_social_only === true,
    website_is_link_in_bio_stub: candidate.website_is_weak === true,
    web_search_used: enrichment.used,
    web_search_note: enrichment.note,
    social_profiles_found: enrichment.socialLinks,
    other_domains_found: enrichment.possibleWebsites,
  };

  const aiBody = {
    model,
    temperature: 0.2,
    max_tokens: 500,
    response_format: SCHEMA,
    messages: [
      { role: 'system', content: SYSTEM_PROMPT },
      {
        role: 'user',
        content:
          'Qualify this business as a website lead. Facts:\n' + JSON.stringify(facts, null, 2),
      },
    ],
  };

  const socialLinks = enrichment.socialLinks.slice(0, 3);
  if (candidate.website_is_social_only === true && candidate.website) {
    if (!socialLinks.includes(candidate.website)) socialLinks.unshift(candidate.website);
  }

  out.push({
    json: Object.assign({}, candidate, {
      enrichment,
      social_links_found: socialLinks,
      has_social_presence: socialLinks.length > 0,
      aiBody,
    }),
  });
}

return out;

// Фільтрує лідів за якістю та лімітами запуску, а потім формує дані точно під колонки Data Table.
// Завжди повертаємо результат, навіть якщо жоден лід не пройшов фільтр.

const cfg = $('Конфігурація').first()?.json ?? {};
const items = $input.all().map((i) => i.json);

const num = (value, fallback) => {
  const n = Number(value);
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : fallback;
};

const testMode = cfg.testMode === true;
const maxLeads = testMode ? num(cfg.testMaxLeads, 3) : num(cfg.maxLeadsPerRun, 15);

const minScoreRaw = Number(cfg.minLeadScore);
const minScore = Number.isFinite(minScoreRaw) ? minScoreRaw : 55;

const qualified = items
  .filter((item) => {
    const a = item.assessment ?? {};
    return a.needs_website === true && Number(a.lead_score) >= minScore;
  })
  .sort((a, b) => Number(b.assessment.lead_score) - Number(a.assessment.lead_score))
  .slice(0, maxLeads);

if (qualified.length === 0) {
  return [{ json: { _noLeads: true } }];
}

const firstSeen = new Date().toISOString();

return qualified.map((item) => ({
  json: {
    place_id: String(item.place_id ?? ''),
    name: String(item.name ?? ''),
    category: String(item.assessment.business_type_normalized || item.category || ''),
    city: String(item.city ?? ''),
    address: String(item.address ?? ''),
    phone: String(item.phone ?? ''),
    website: String(item.website ?? ''),
    maps_url: String(item.maps_url ?? ''),
    has_website: false,
    has_social: item.has_social_presence === true,
    social_links: Array.isArray(item.social_links_found) ? item.social_links_found.join(' , ') : '',
    rating: Number(item.rating) || 0,
    reviews: Number(item.reviews) || 0,
    lead_score: Number(item.assessment.lead_score) || 0,
    lead_reason: String(item.assessment.reason ?? ''),
    pitch_angle: String(item.assessment.pitch_angle ?? ''),
    recommended_service: String(item.assessment.recommended_service ?? ''),
    ai_status: String(item.ai_status ?? 'ok'),
    first_seen: firstSeen,
    status: 'new',
  },
}));

// Обробляє відповідь OpenAI для кожного кандидата.
// Якщо AI повернув помилку або некоректну відповідь, використовуємо резервну оцінку.

const candidates = $('формування запиту до ліда').all().map((i) => i.json);
const items = $input.all();

const ALLOWED_SERVICES = [
  'landing_page',
  'multi_page_site',
  'online_store',
  'booking_site',
  'portfolio_site',
  'google_business_only',
];

function extractJson(text) {
  if (typeof text !== 'string') return null;
  let t = text.trim();
  if (!t) return null;

  const fenced = t.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fenced) t = fenced[1].trim();

  try {
    return JSON.parse(t);
  } catch {
    // Якщо звичайний парсинг не спрацював, шукаємо JSON усередині тексту.
  }

  const first = t.indexOf('{');
  const last = t.lastIndexOf('}');
  if (first !== -1 && last > first) {
    try {
      return JSON.parse(t.slice(first, last + 1));
    } catch {
      return null;
    }
  }
  return null;
}

// Резервна оцінка, щоб помилка AI не призвела до втрати ліда.
function heuristic(candidate) {
  let score = 55;
  const reviews = Number(candidate.reviews) || 0;
  const rating = Number(candidate.rating) || 0;

  if (reviews >= 100) score += 18;
  else if (reviews >= 30) score += 12;
  else if (reviews >= 10) score += 6;
  else if (reviews === 0) score -= 15;

  if (rating >= 4.5) score += 8;
  else if (rating >= 4.0) score += 4;

  if (candidate.has_social_presence === true) score += 8;
  if (!candidate.website) score += 5;

  score = Math.max(0, Math.min(100, score));

  return {
    needs_website: true,
    lead_score: score,
    confidence: 'low',
    business_type_normalized: candidate.category || candidate.google_type || '',
    reason: 'Оцінено автоматично (без AI): бізнес без власного сайту.',
    pitch_angle: 'Запропонувати простий сайт-візитівку замість сторінки в соцмережах.',
    recommended_service: 'landing_page',
    red_flags: [],
  };
}

function clampScore(value, fallback) {
  const n = Number(value);
  if (!Number.isFinite(n)) return fallback;
  return Math.max(0, Math.min(100, Math.round(n)));
}

function asText(value, fallback) {
  return typeof value === 'string' && value.trim() ? value.trim().slice(0, 500) : fallback;
}

const out = [];

for (let i = 0; i < candidates.length; i++) {
  const candidate = candidates[i];
  const response = items[i]?.json ?? {};

  let assessment = null;
  let aiStatus = 'ok';
  let aiNote = '';

  if (response.error) {
    aiStatus = 'fallback';
    aiNote = 'AI request failed';
  } else {
    const choice = Array.isArray(response.choices) ? response.choices[0] : null;
    const refusal = choice?.message?.refusal;

    if (refusal) {
      aiStatus = 'fallback';
      aiNote = 'AI refused to answer';
    } else {
      const parsed = extractJson(choice?.message?.content);
      if (!parsed || typeof parsed !== 'object') {
        aiStatus = 'fallback';
        aiNote = 'AI output was not valid JSON';
      } else {
        assessment = parsed;
      }
    }
  }

  const fallback = heuristic(candidate);

  if (!assessment) {
    assessment = fallback;
  }

  const service = asText(assessment.recommended_service, fallback.recommended_service);
  const confidence = asText(assessment.confidence, 'low').toLowerCase();

  const clean = {
    needs_website: assessment.needs_website === false ? false : true,
    lead_score: clampScore(assessment.lead_score, fallback.lead_score),
    confidence: ['low', 'medium', 'high'].includes(confidence) ? confidence : 'low',
    business_type_normalized: asText(
      assessment.business_type_normalized,
      fallback.business_type_normalized,
    ),
    reason: asText(assessment.reason, fallback.reason),
    pitch_angle: asText(assessment.pitch_angle, fallback.pitch_angle),
    recommended_service: ALLOWED_SERVICES.includes(service) ? service : 'landing_page',
    red_flags: Array.isArray(assessment.red_flags)
      ? assessment.red_flags.filter((f) => typeof f === 'string').slice(0, 5)
      : [],
  };

  out.push({
    json: Object.assign({}, candidate, {
      assessment: clean,
      ai_status: aiStatus,
      ai_note: aiNote,
    }),
  });
}

return out;
